# Auto-generated by RasoSynthTune for Unsloth
# Base Model: sarvamai/sarvam-2b-v0.5 | Paradigm: SFT

from unsloth import FastLanguageModel, is_bfloat16_supported
from datasets import load_dataset
import torch

max_seq_length = 2048
dtype = None # Auto detection: Float16 or Bfloat16
load_in_4bit = True

# 1. Load Model & Tokenizer
model, tokenizer = FastLanguageModel.from_pretrained(
    model_name="sarvamai/sarvam-2b-v0.5",
    max_seq_length=max_seq_length,
    dtype=dtype,
    load_in_4bit=load_in_4bit,
)

# 2. Configure Parameter-Efficient LoRA Adapters
model = FastLanguageModel.get_peft_model(
    model,
    r=16,
    target_modules=["q_proj", "k_proj", "v_proj", "o_proj", "gate_proj", "up_proj", "down_proj"],
    lora_alpha=32,
    lora_dropout=0, # Optimized 0 dropout for Unsloth
    bias="none",
    use_gradient_checkpointing="unsloth",
    random_state=3407,
)

# 3. Load Dataset
dataset = load_dataset("json", data_files="flagship_indic_gst_sft.jsonl")

# 4. Train Model
from trl import SFTTrainer
from transformers import TrainingArguments

training_args = TrainingArguments(
    output_dir="./lora_adapters",
    per_device_train_batch_size=4,
    gradient_accumulation_steps=4,
    learning_rate=0.0002,
    lr_scheduler_type="cosine",
    warmup_ratio=0.05,
    fp16=not is_bfloat16_supported(),
    bf16=is_bfloat16_supported(),
    logging_steps=10,
    save_strategy="steps",
    save_steps=200,
    num_train_epochs=3,
    optim="adamw_8bit",
)

trainer = SFTTrainer(
    model=model,
    tokenizer=tokenizer,
    train_dataset=dataset["train"],
    dataset_text_field="text",
    max_seq_length=2048,
    dataset_num_proc=2,
    args=training_args,
)
trainer.train()

# 5. Save LoRA Adapters & GGUF
model.save_pretrained_merged("./lora_adapters/merged_16bit", tokenizer, save_method="merged_16bit")
print("Training complete! Model exported to ./lora_adapters")
